def is_leap(year: int) -> bool:
    """Return whether the year is a leap year in the Gregorian calendar: divisible by 4, except century years, which are leap years only when divisible by 400."""
    raise NotImplementedError
from solution import is_leap

def test_is_leap_0():
    assert is_leap(2024) == True

def test_is_leap_1():
    assert is_leap(2023) == False

def test_is_leap_2():
    assert is_leap(2000) == True

def test_is_leap_3():
    assert is_leap(1900) == True

def test_is_leap_4():
    assert is_leap(2100) == False

